SELECT analytics_order_facts.category, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 5 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'education' AND analytics_order_facts.category = 'category_09' GROUP BY analytics_order_facts.category ORDER BY net_revenue DESC, analytics_order_facts.category ASC LIMIT 10
